import{_ as t,a8 as r,o as c,c as p,ah as n,db as s,dc as i,dd as d,de as b,df as u,dg as g,dh as k,di as h,K as o}from"./chunks/framework.CgKDWdj8.js";import"./chunks/theme.CCmhGRzB.js";const _="",N=JSON.parse('{"title":"聚类","description":"","frontmatter":{"title":"聚类","abstract":"聚类算法讲解，作为无监督学习方法介绍其核心思想与现实应用，重点讲解 K-Means 算法的原理与实现。","created":"2026-03-28T00:00:00.000Z","tags":["机器学习","聚类","无监督"],"type":"概念解释","related":[],"reference":[],"category":["🤖 AI大模型","机器学习"]},"headers":[],"relativePath":"vault/Knowledge/AI/机器学习-聚类.md","filePath":"vault/Knowledge/AI/机器学习-聚类.md","lastUpdated":1790655645000}'),v={name:"vault/Knowledge/AI/机器学习-聚类.md"};function m(f,a,y,x,K,q){const l=r("NolebaseGitContributors"),e=r("NolebaseGitChangelog");return c(),p("div",null,[a[0]||(a[0]=n('<h1 id="聚类" tabindex="-1">聚类 <a class="header-anchor" href="#聚类" aria-label="Permalink to “聚类”">​</a></h1><h1 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to “基本概念”">​</a></h1><h3 id="什么是聚类算法" tabindex="-1">什么是聚类算法 <a class="header-anchor" href="#什么是聚类算法" aria-label="Permalink to “什么是聚类算法”">​</a></h3><p>聚类算法是一种<span data-type="text" style="background-color:var(--b3-card-error-background);color:var(--b3-card-error-color);">无监督学习</span> 方法，其核心思想是：</p><blockquote><p>根据<span data-type="text" style="background-color:var(--b3-card-error-background);color:var(--b3-card-error-color);">样本之间的相似性</span>，将数据自动划分为若干个类别（簇），使得同一簇内的样本尽可能相似，而不同簇之间的样本尽可能不同。</p></blockquote><ul><li><p><strong>相似性度量</strong>是关键：常用的计算方式包括<strong>欧式距离</strong>、曼哈顿距离、余弦相似度等。不同的相似度标准可能导致不同的聚类结果。</p></li><li><p><strong>目标</strong>：揭示数据中隐藏的分组规律，帮助我们理解数据的分布特征。</p><blockquote><p>✅ 举个例子：</p></blockquote><blockquote><p>在客户数据分析中，聚类可以自动将用户分为“高消费高收入”、“低消费高收入”等群体，帮助企业制定精准营销策略。</p></blockquote><blockquote></blockquote></li><li><p><strong>聚类结果受准则影响</strong>：<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">使用不同的聚类算法</span>（如 K-Means、DBSCAN）或参数设置，<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">会产生不同的聚类效果</span>，因此选择合适的算法和评估指标非常重要。</p></li></ul><p>|关键点|内容|</p><p>| --------| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|</p><p>|本质|无监督学习算法|</p><p>|依据|样本间的相似性（如距离）|</p><p>|目的|在<span data-type="text" style="background-color:var(--b3-card-error-background);color:var(--b3-card-error-color);">没有先验知识</span>的情况下，自动发现数据的<span data-type="text" style="background-color:var(--b3-card-error-background);color:var(--b3-card-error-color);">内在结构和模式</span>|</p><p>|特点|不依赖标签，自动分组|</p><p>|输出|多个簇（Cluster），每个簇代表一个群体|</p><h3 id="聚类算法在现实中的应用" tabindex="-1">聚类算法在现实中的应用 <a class="header-anchor" href="#聚类算法在现实中的应用" aria-label="Permalink to “聚类算法在现实中的应用”">​</a></h3><p><img src="'+s+'"></p><h3 id="聚类算法-分类" tabindex="-1">聚类算法 分类 <a class="header-anchor" href="#聚类算法-分类" aria-label="Permalink to “聚类算法 分类”">​</a></h3><ol><li><h6 id="按照聚类颗粒度划分-细聚类-vs-粗聚类" tabindex="-1">按照聚类颗粒度划分：细聚类 vs 粗聚类 <a class="header-anchor" href="#按照聚类颗粒度划分-细聚类-vs-粗聚类" aria-label="Permalink to “按照聚类颗粒度划分：细聚类 vs 粗聚类”">​</a></h6><p><img src="'+i+'"></p><p>|类型|特点|图解说明|</p><p>| --------| ------------------------------------------------------------------------------| ------------------------------------------------------------------------------|</p><p>|细聚类|将数据划分为多个较小的、独立的簇，每个簇代表一个具体的子群体。|如左图所示，每个椭圆圈出一组紧密聚集的点，表示对数据进行了细致划分。|</p><p>|粗聚类|在细聚类的基础上进一步合并相似的簇，形成更大的类别，体现更高层次的分组结构。|如右图所示，蓝色虚线将多个细粒度簇组合成两个更大的“超级簇”，用于宏观分析。|</p><blockquote><p>✅ <strong>应用场景对比</strong>：</p></blockquote><blockquote></blockquote><blockquote><ul><li>细聚类适用于需要精细用户画像或细分市场分析。</li></ul></blockquote><blockquote><ul><li>粗聚类适合快速了解整体结构，常用于探索性数据分析。</li></ul></blockquote><blockquote></blockquote></li><li><h6 id="按照实现方法分类-常见聚类算法" tabindex="-1">按照实现方法分类（常见聚类算法） <a class="header-anchor" href="#按照实现方法分类-常见聚类算法" aria-label="Permalink to “按照实现方法分类（常见聚类算法）”">​</a></h6><p>|算法名称|核心思想|特点与适用场景|</p><p>| -------------------------------------| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------| -------------------------------------------------------------------------------------------------------------------------------------------------------------|</p><p>|K-Means|基于<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">质心</span>的聚类方法，通过迭代更新簇中心，使样本到其所属簇中心的距离最小化。|✅ <span data-type="text" style="background-color:var(--b3-card-error-background);color:var(--b3-card-error-color);">通用性强</span>、计算效率高<br>❌ 需预先指定簇数 KK ，且假设簇为球形分布|</p><p>|层次聚类（Hierarchical Clustering）|对数据进行<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">逐层划分（自底向上）</span>或<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">合并（自顶向下）</span>，构建树状结构（Dendrogram）。|✅ 不需预设簇数，能展示聚类过程<br>❌ 计算复杂度较高，不适合大数据集|</p><p>|DBSCAN|基于<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">密度</span>的聚类算法，能够识别任意形状的簇，并自动发现噪声点（离群点）。|✅ 可处理非球形簇，抗噪声能力强<br>❌ 对参数敏感，稀疏区域可能误判|</p><p>|谱聚类（Spectral Clustering）|基于<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">图论</span>思想，将数据视为图中的节点，利用图的拉普拉斯矩阵进行降维后再聚类。|✅ 适合复杂结构数据，如环形、月牙形分布<br>❌ 计算成本较高，依赖邻接图构造|</p></li></ol><ul><li><h6 id="如何选择合适的聚类算法" tabindex="-1">如何选择合适的聚类算法？ <a class="header-anchor" href="#如何选择合适的聚类算法" aria-label="Permalink to “如何选择合适的聚类算法？”">​</a></h6><p>|数据特点|推荐算法|</p><p>| --------------------------------| ----------|</p><p>|数据分布均匀、簇为球形|K-Means|</p><p>|需要可视化聚类过程、无固定簇数|层次聚类|</p><p>|存在噪声、簇形状不规则|DBSCAN|</p><p>|数据具有复杂拓扑结构|谱聚类|</p><ul><li><p>“颗粒度”反映的是<strong>聚类的精细程度</strong>，细聚类更注重细节，粗聚类关注整体趋势。</p></li><li><p>实现方法决定了算法的<strong>假设前提、性能表现和适用范围</strong>。</p></li><li><p>实际应用中，通常先尝试 K-Means，再结合业务需求选择其他高级算法。</p></li></ul></li></ul><h1 id="k-means" tabindex="-1">K-Means <a class="header-anchor" href="#k-means" aria-label="Permalink to “K-Means”">​</a></h1><p>KMeans <span data-type="text" style="background-color:var(--b3-card-success-background);color:var(--b3-card-success-color);">算法实现流程</span></p><ol><li><p>事先确定<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">常数 K</span>，表示最终要划分的聚类类别数。</p><ul><li>K 必须预先指定，通常通过肘部法则或轮廓系数确定。</li></ul></li><li><p>初始化 <span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">K 个聚类中心</span>：</p><ul><li><p>传统方法：随机从样本中选择 K 个点；</p></li><li><p>推荐方法：使用 k-means++ 智能初始化，提高稳定性。</p></li></ul></li><li><p>计算<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">每个样本到 K 个中心的欧氏距离</span>，将其分配给最近的聚类中心。</p><ul><li>注意：若特征尺度差异大，需先对数据进行标准化处理。</li></ul></li><li><p>根据当前分配结果，重新<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">计算每个簇的中心</span>（即该簇内所有样本的均值）。</p></li><li><p>判断是否收敛：</p><ul><li><p>若<span data-type="text" style="background-color:var(--b3-card-info-background);color:var(--b3-card-info-color);">新中心与旧中心的变化小于设定阈值</span>（如 tol=1e-4），则停止迭代；</p></li><li><p>否则返回第 3 步继续迭代，直到中心不再显著变化。</p></li></ul></li><li><p>输出结果：</p><ul><li><p>每个样本的聚类标签（labels_）</p></li><li><p>每个簇的中心坐标（cluster_centers_）</p></li><li><p>总惯性（inertia_）：衡量簇内紧密程度</p></li></ul></li></ol><p><video controls="controls" src="'+_+'" data-src="assets/KMeans过程-20260130163739-mxgjkhq.mp4"></video></p><p>【示例】</p><p><img src="'+d+'"></p><p><img src="'+b+'"></p><p><img src="'+u+'"></p><p><img src="'+g+'"></p><p><img src="'+k+'"></p><p><img src="'+h+'"></p><p>‍</p><hr>',31)),o(l),o(e)])}const A=t(v,[["render",m]]);export{N as __pageData,A as default};
